using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct ItemStackId : IEquatable<ItemStackId>, IComparable<ItemStackId>
    {
        public Guid Value { get; }

        public ItemStackId(Guid value)
        {
            Value = value;
        }

        public static ItemStackId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static ItemStackId NewRandom() => new ItemStackId(Guid.NewGuid());

        public static ItemStackId Parse(string text) => new ItemStackId(Guid.Parse(text));

        public static bool TryParse(string text, out ItemStackId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new ItemStackId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(ItemStackId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is ItemStackId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(ItemStackId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(ItemStackId left, ItemStackId right) => left.Equals(right);

        public static bool operator !=(ItemStackId left, ItemStackId right) => !left.Equals(right);
    }
}
